$source=@'
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;
public class SrtpDecode {
static int U(byte[]b,int p){return b[p]*256+b[p+1];}static uint V(byte[]b,int p){return(uint)((b[p]<<24)|(b[p+1]<<16)|(b[p+2]<<8)|b[p+3]);}static byte[] S(byte[]b,int p,int n){var r=new byte[n];Array.Copy(b,p,r,0,n);return r;}
static byte[] Ctr(byte[]key,byte[]iv,int len){using(var aes=Aes.Create()){aes.Key=key;aes.Mode=CipherMode.ECB;aes.Padding=PaddingMode.None;using(var enc=aes.CreateEncryptor()){var o=new byte[len];for(int p=0;p<len;p+=16){var z=enc.TransformFinalBlock(iv,0,16);Array.Copy(z,0,o,p,Math.Min(16,len-p));for(int i=15;i>=0;i--)if(++iv[i]!=0)break;}return o;}}}
class K {public byte[] enc,auth,salt;public K(byte[]m){byte[]key=S(m,0,16),salt=S(m,16,14);Func<int,int,byte[]> d=(label,n)=>{var iv=new byte[16];Array.Copy(salt,iv,14);iv[7]^=(byte)label;return Ctr(key,iv,n);};enc=d(0,16);auth=d(1,20);this.salt=d(2,14);}}
class Flow {public K key;public uint roc;public int last=-1;public MemoryStream audio=new MemoryStream();}
public static void Run(string path,string keyfile,string folder){Directory.CreateDirectory(folder);var keys=File.ReadLines(keyfile).Select(l=>l.Split(' ').Last()).Distinct().Select(x=>new K(Convert.FromBase64String(x))).ToList();var flows=new Dictionary<string,Flow>();var b=File.ReadAllBytes(path);int ok=0,fail=0;for(int p=24;p+16<b.Length;){int n=BitConverter.ToInt32(b,p+8),s=p+16,end=s+n,ip=s+14;if(end>b.Length)break;if(U(b,s+12)==2048&&b[ip+9]==17){int tr=ip+(b[ip]&15)*4,d=tr+8,len=U(b,tr+4)-8;if(len>=22&&(b[d]>>6)==2&&(b[d+1]&127)==0){int sp=U(b,tr),dp=U(b,tr+2);string name=string.Join(".",S(b,ip+12,4))+"_"+sp+"_to_"+string.Join(".",S(b,ip+16,4))+"_"+dp+"_"+V(b,d+8).ToString("x8");if(!flows.ContainsKey(name))flows[name]=new Flow();var f=flows[name];int seq=U(b,d+2);uint roc=f.roc;if(f.last>=0&&seq<f.last-32768)roc++;var msg=new byte[len-10+4];Array.Copy(b,d,msg,0,len-10);msg[msg.Length-4]=(byte)(roc>>24);msg[msg.Length-3]=(byte)(roc>>16);msg[msg.Length-2]=(byte)(roc>>8);msg[msg.Length-1]=(byte)roc;foreach(var k in f.key==null?keys:new List<K>{f.key}){using(var h=new HMACSHA1(k.auth)){var tag=h.ComputeHash(msg);bool match=true;for(int z=0;z<10;z++)if(tag[z]!=b[d+len-10+z])match=false;if(!match)continue;f.key=k;break;}}if(f.key==null){fail++;}else{f.roc=roc;f.last=seq;var iv=new byte[16];Array.Copy(f.key.salt,iv,14);for(int z=0;z<4;z++)iv[4+z]^=b[d+8+z];ulong idx=((ulong)roc<<16)|(uint)seq;for(int z=0;z<6;z++)iv[13-z]^=(byte)(idx>>(z*8));int hd=12+4*(b[d]&15);if((b[d]&16)!=0)hd+=4+4*U(b,d+hd+2);int count=len-hd-10;var plain=Ctr(f.key.enc,iv,count);for(int z=0;z<count;z++)plain[z]^=b[d+hd+z];f.audio.Write(plain,0,count);ok++;}}}p=end;}
foreach(var kv in flows)if(kv.Value.audio.Length>0)File.WriteAllBytes(Path.Combine(folder,kv.Key+".ulaw"),kv.Value.audio.ToArray());Console.WriteLine("Decrypted "+ok+" failed "+fail+" streams "+flows.Count);}}
'@
Add-Type -TypeDefinition $source
[SrtpDecode]::Run((Join-Path $PWD 'DontLeaveMeHanging.pcap'),(Join-Path $PWD 'srtp_keys.txt'),(Join-Path $PWD 'call_audio'))
